if(!EditorApplication.isPlaying)throw new System.Exception("Play only");string D="ArtSource/Pipeline/Review/BriarwickWoodland04";var player=GameObject.Find("BB_Explorer_Locomotion03");var cc=player.GetComponent<CharacterController>();var motor=player.GetComponent<BlightBloom.Traversal.ThirdPersonMotor>();var orbit=Camera.main.GetComponent<BlightBloom.Traversal.ThirdPersonOrbitCamera>();var saved=player.transform.position;var rot=player.transform.rotation;bool me=motor.enabled,oe=orbit.enabled;var results=new System.Collections.Generic.List<object>();var terrain=Terrain.activeTerrain;
