}finally{cc.enabled=false;player.transform.SetPositionAndRotation(saved,rot);cc.enabled=true;motor.enabled=me;orbit.enabled=oe;Physics.SyncTransforms();}var report=new{method="Existing CharacterController.Move, automated Play-mode collision test; not keyboard/manual camera validation",controller=new{cc.height,cc.radius},results,normalStateRestored=motor.enabled==me&&orbit.enabled==oe,allPass=results.All(x=>(bool)x.GetType().GetProperty("pass").GetValue(x)&&(bool)x.GetType().GetProperty("grounded").GetValue(x))};System.IO.File.WriteAllText(D+"/PlayValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;
